"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41676"],{46645(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.nota_minima_sem_carater_que_elimina","status":422,"titulo":"Nota m\xednima s\xf3 se aplica a etapa cujo car\xe1ter elimina"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.nota_minima_sem_carater_que_elimina","requisitos":[],"oQueAconteceu":["Uma das etapas do pedido de defini\xe7\xe3o de etapas\\n(`PUT .../processos-seletivos/{id}/etapas`) tem car\xe1ter **classificat\xf3rio** e traz\\n`notaMinima`. A nota m\xednima \xe9 o corte que reprova o candidato, e s\xf3 tem sentido na\\netapa cujo car\xe1ter elimina (eliminat\xf3ria ou ambas); a etapa apenas classificat\xf3ria\\npontua sem reprovar, e a nota m\xednima ficaria gravada sem efeito. A recusa vem em\\n`etapas[n].notaMinima`.","A confer\xeancia \xe9 da primeira passada, que confere a forma de todas as etapas do\\npedido antes de consultar o cat\xe1logo de tipos de etapa, e acumula as viola\xe7\xf5es de\\ntodas as etapas no array `errors[]`\\n(ver [`nome_obrigatorio`](/erros/uniplus.selecao.etapa_processo.nome_obrigatorio)). A\\nnota m\xednima negativa \xe9 recusada antes, como\\n[`nota_minima_invalida`](/erros/uniplus.selecao.etapa_processo.nota_minima_invalida), e\\nas duas recusas n\xe3o aparecem juntas para a mesma etapa."],"comoResolver":["Retire a `notaMinima` da etapa classificat\xf3ria. Se a etapa deve eliminar\\ncandidatos pela nota, mude o car\xe1ter para eliminat\xf3ria ou ambas e mantenha a nota\\nm\xednima. Se a resposta trouxer outras viola\xe7\xf5es em `errors[]`, corrija todas antes\\nde reenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);